-- Phase O: shared, durable editorial agents and two independently fulfilled VIP audiences.
alter table public.telegram_audience_configuration drop constraint if exists telegram_audience_configuration_audience_check;
alter table public.telegram_audience_configuration drop constraint if exists telegram_audience_configuration_product_code_key;
alter table public.telegram_audience_configuration add constraint telegram_audience_configuration_audience_check check(audience in('FREE','VIP','VIP_FOREX_GOLD','VIP_CRYPTO','EXECUTION','ADMIN','OWNER'));
insert into public.telegram_audience_configuration(audience,product_code,enabled) values('VIP_FOREX_GOLD','VIP_SIGNALS',false),('VIP_CRYPTO','VIP_SIGNALS',false) on conflict(audience) do nothing;

create or replace function public.phase_o_enqueue_vip_audiences() returns trigger language plpgsql security definer set search_path=public as $$
declare action text; audience text;
begin
 if new.product_code<>'VIP_SIGNALS' then return new; end if;
 action:=case when new.state in('ACTIVE','TRIAL','GRACE') then case when tg_op='INSERT' then 'ADD' else 'RESTORE' end when new.state in('PENDING','SUSPENDED') then 'SUSPEND' else 'REMOVE' end;
 foreach audience in array array['VIP_FOREX_GOLD','VIP_CRYPTO'] loop
  insert into telegram_fulfillment_requests(customer_id,entitlement_id,access_type,audience,action,idempotency_key,entitlement_version)
  values(new.customer_id,new.id,new.product_code,audience,action,'phase-o:'||new.id||':'||audience||':'||action||':'||new.state||':'||coalesce(new.valid_until::text,'none'),new.updated_at) on conflict(idempotency_key) do nothing;
 end loop; return new;
end$$;
drop trigger if exists trg_phase_o_vip_audiences on public.phase_h_entitlements;
create trigger trg_phase_o_vip_audiences after insert or update of state,valid_until on public.phase_h_entitlements for each row execute function public.phase_o_enqueue_vip_audiences();
-- Preserve existing membership evidence. Backfill only fulfillment requests, never membership rows.
insert into public.telegram_fulfillment_requests(customer_id,entitlement_id,access_type,audience,action,idempotency_key,entitlement_version)
select e.customer_id,e.id,e.product_code,a.audience,case when e.state in('ACTIVE','TRIAL','GRACE') then 'ADD' when e.state in('PENDING','SUSPENDED') then 'SUSPEND' else 'REMOVE' end,'phase-o:backfill:'||e.id||':'||a.audience,e.updated_at
from public.phase_h_entitlements e cross join(values('VIP_FOREX_GOLD'),('VIP_CRYPTO'))a(audience) where e.product_code='VIP_SIGNALS' on conflict(idempotency_key) do nothing;

create table public.phase_o_agent_configurations(
 role text primary key check(role in('CONTENT_PROOF','GROWTH_ENGAGEMENT','CUSTOMER_GUIDE')),enabled boolean not null default false,model text not null default 'gemini-3.7-flash',languages text[] not null default array['en','so'],max_requests_per_run integer not null default 5 check(max_requests_per_run between 1 and 20),timeout_ms integer not null default 15000 check(timeout_ms between 1000 and 30000),monthly_budget_units integer not null default 0 check(monthly_budget_units>=0),paused_at timestamptz,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
insert into public.phase_o_agent_configurations(role) values('CONTENT_PROOF'),('GROWTH_ENGAGEMENT'),('CUSTOMER_GUIDE') on conflict do nothing;
create table public.phase_o_campaigns(id uuid primary key default gen_random_uuid(),name text not null,source_code text,canonical_url text not null,language text not null check(language in('en','so')),status text not null default 'DRAFT' check(status in('DRAFT','ACTIVE','PAUSED','CANCELLED','COMPLETE')),offer_code text check(offer_code is null or offer_code in('VIP_SIGNALS_7D_KES_1200','VIP_SIGNALS_30D_KES_3500','VIP_SIGNALS_MONTHLY_USD_29')),budget_units integer not null default 0 check(budget_units>=0),spent_units integer not null default 0 check(spent_units>=0),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.phase_o_destinations(id uuid primary key default gen_random_uuid(),platform text not null check(platform in('TELEGRAM','MANUAL_EXPORT')),audience text not null check(audience in('FREE','VIP_FOREX_GOLD','VIP_CRYPTO','CUSTOMER')),label text not null,external_identity_ref text,enabled boolean not null default false,configuration_state text not null default 'UNCONFIGURED' check(configuration_state in('UNCONFIGURED','READY','DEGRADED','REVOKED')),allowed_content_types text[] not null default array['TEXT'],max_per_hour integer not null default 1 check(max_per_hour between 1 and 100),approval_required boolean not null default true,permission_verified_at timestamptz,created_at timestamptz not null default now(),unique(platform,audience,label));
create table public.phase_o_agent_jobs(id uuid primary key default gen_random_uuid(),role text not null references phase_o_agent_configurations(role),task text not null check(task in('MARKET_CONTEXT','EDUCATION','SIGNAL_RECAP','OUTCOME_RECAP','PROOF_CARD','UPGRADE_POST','SOCIAL_EXPORT','CUSTOMER_GUIDANCE')),language text not null check(language in('en','so')),campaign_id uuid references phase_o_campaigns(id),evidence_refs jsonb not null default '[]',destination_id uuid references phase_o_destinations(id),content_type text not null default 'TEXT' check(content_type in('TEXT','CHART','PROOF_CARD','VIDEO_BRIEF')),status text not null default 'QUEUED' check(status in('QUEUED','CLAIMED','DRAFTED','AWAITING_APPROVAL','APPROVED','DELIVERING','COMPLETED','PAUSED','CANCELLED','FAILED','DEAD_LETTER','UNCERTAIN')),attempt integer not null default 0,max_attempts integer not null default 5 check(max_attempts between 1 and 10),available_at timestamptz not null default now(),lease_token uuid,lease_owner text,lease_expires_at timestamptz,checkpoint jsonb not null default '{}',safe_error text check(length(safe_error)<=240),requested_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index phase_o_agent_job_claim on public.phase_o_agent_jobs(status,available_at,lease_expires_at);
create table public.phase_o_drafts(id uuid primary key default gen_random_uuid(),job_id uuid not null references phase_o_agent_jobs(id),version integer not null check(version>0),content text not null,content_hash text not null,artifact_id uuid,destination_id uuid references phase_o_destinations(id),offer_code text,usage_units integer not null default 0,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(job_id,version));
create table public.phase_o_approvals(id uuid primary key default gen_random_uuid(),draft_id uuid not null references phase_o_drafts(id),draft_version integer not null,binding_hash text not null,scope text not null default 'ONE_TIME' check(scope in('ONE_TIME','STANDING_TEMPLATE')),max_uses integer not null default 1,expires_at timestamptz,approved_by uuid not null references auth.users(id),approved_at timestamptz not null default now(),revoked_at timestamptz);
create table public.phase_o_artifacts(id uuid primary key default gen_random_uuid(),job_id uuid not null references phase_o_agent_jobs(id),kind text not null check(kind in('GENERATED_CHART','GENERATED_PROOF_CARD','IMPORTED_SCREENSHOT')),storage_path text not null unique,source_ref text not null,source_timestamp timestamptz not null,signal_id uuid,trade_id uuid,run_id uuid,dataset_lineage jsonb not null,classification text not null check(classification in('PAPER','DEMO','REPLAY','LIVE')),content_hash text not null,template_version text not null,consent_ref text,redaction_policy text not null,access_policy text not null,created_at timestamptz not null default now());
alter table public.phase_o_drafts add constraint phase_o_draft_artifact_fk foreign key(artifact_id) references public.phase_o_artifacts(id);
create table public.phase_o_delivery_parts(id uuid primary key default gen_random_uuid(),draft_id uuid not null references phase_o_drafts(id),part integer not null default 0,identity text not null unique,state text not null check(state in('RESERVED','DELIVERED','RETRY','DEAD','UNCERTAIN')),provider_message_id text,safe_error text,attempt integer not null default 0,next_attempt_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.phase_o_usage(id uuid primary key default gen_random_uuid(),job_id uuid not null references phase_o_agent_jobs(id),campaign_id uuid references phase_o_campaigns(id),role text not null,model text,usage_units integer not null check(usage_units>=0),created_at timestamptz not null default now());
create table public.phase_o_audit(id bigint generated always as identity primary key,actor_id uuid,event_type text not null,entity_type text not null,entity_id text not null,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.phase_o_attribution_events(id uuid primary key default gen_random_uuid(),anonymous_id text,customer_id uuid references auth.users(id),campaign_id uuid references phase_o_campaigns(id),event_type text not null check(event_type in('LANDING_VISIT','CLICK','SIGNUP','CHECKOUT_ATTEMPT','ENTITLEMENT_VERIFIED','TELEGRAM_LINKED','MEMBERSHIP_CONFIRMED','RENEWED','CHURNED')),audience text,occurred_at timestamptz not null,source_ref text,idempotency_key text not null unique);

alter table public.phase_o_agent_configurations enable row level security;alter table public.phase_o_campaigns enable row level security;alter table public.phase_o_destinations enable row level security;alter table public.phase_o_agent_jobs enable row level security;alter table public.phase_o_drafts enable row level security;alter table public.phase_o_approvals enable row level security;alter table public.phase_o_artifacts enable row level security;alter table public.phase_o_delivery_parts enable row level security;alter table public.phase_o_usage enable row level security;alter table public.phase_o_audit enable row level security;alter table public.phase_o_attribution_events enable row level security;
create policy phase_o_admin_config on public.phase_o_agent_configurations for select to authenticated using(public.is_admin());create policy phase_o_admin_campaign on public.phase_o_campaigns for select to authenticated using(public.is_admin());create policy phase_o_admin_destination on public.phase_o_destinations for select to authenticated using(public.is_admin());create policy phase_o_admin_job on public.phase_o_agent_jobs for select to authenticated using(public.is_admin());create policy phase_o_admin_draft on public.phase_o_drafts for select to authenticated using(public.is_admin());create policy phase_o_admin_approval on public.phase_o_approvals for select to authenticated using(public.is_admin());create policy phase_o_admin_artifact on public.phase_o_artifacts for select to authenticated using(public.is_admin());create policy phase_o_admin_delivery on public.phase_o_delivery_parts for select to authenticated using(public.is_admin());create policy phase_o_admin_usage on public.phase_o_usage for select to authenticated using(public.is_admin());create policy phase_o_admin_audit on public.phase_o_audit for select to authenticated using(public.is_admin());create policy phase_o_admin_attr on public.phase_o_attribution_events for select to authenticated using(public.is_admin());
revoke all on public.phase_o_agent_configurations,public.phase_o_campaigns,public.phase_o_destinations,public.phase_o_agent_jobs,public.phase_o_drafts,public.phase_o_approvals,public.phase_o_artifacts,public.phase_o_delivery_parts,public.phase_o_usage,public.phase_o_audit,public.phase_o_attribution_events from anon,authenticated;grant select on public.phase_o_agent_configurations,public.phase_o_campaigns,public.phase_o_destinations,public.phase_o_agent_jobs,public.phase_o_drafts,public.phase_o_approvals,public.phase_o_artifacts,public.phase_o_delivery_parts,public.phase_o_usage,public.phase_o_audit,public.phase_o_attribution_events to authenticated;grant all on public.phase_o_agent_configurations,public.phase_o_campaigns,public.phase_o_destinations,public.phase_o_agent_jobs,public.phase_o_drafts,public.phase_o_approvals,public.phase_o_artifacts,public.phase_o_delivery_parts,public.phase_o_usage,public.phase_o_audit,public.phase_o_attribution_events to service_role;

create or replace function public.claim_phase_o_agent_jobs(p_worker text,p_limit integer default 5,p_lease_seconds integer default 60) returns setof public.phase_o_agent_jobs language plpgsql security definer set search_path=public as $$declare token uuid:=gen_random_uuid();begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_limit not between 1 and 20 or p_lease_seconds not between 10 and 300 then raise exception 'UNSAFE_CLAIM_BOUNDS';end if;update phase_o_agent_jobs set status='DEAD_LETTER',safe_error='MAX_ATTEMPTS_EXHAUSTED',lease_token=null,lease_owner=null,lease_expires_at=null where status='CLAIMED' and lease_expires_at<now() and attempt>=max_attempts;return query with picked as(select id from phase_o_agent_jobs where available_at<=now() and attempt<max_attempts and(status='QUEUED' or(status='CLAIMED' and lease_expires_at<now())) order by created_at for update skip locked limit p_limit)update phase_o_agent_jobs j set status='CLAIMED',attempt=j.attempt+1,lease_token=token,lease_owner=p_worker,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),updated_at=now() from picked where j.id=picked.id returning j.*;end$$;
create or replace function public.finish_phase_o_agent_job(p_id uuid,p_lease_token uuid,p_status text,p_checkpoint jsonb default '{}',p_safe_error text default null) returns boolean language plpgsql security definer set search_path=public as $$declare n integer;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_status not in('DRAFTED','AWAITING_APPROVAL','COMPLETED','FAILED','DEAD_LETTER','UNCERTAIN') then raise exception 'INVALID_JOB_STATUS';end if;update phase_o_agent_jobs set status=p_status,checkpoint=coalesce(p_checkpoint,'{}'),safe_error=left(p_safe_error,240),available_at=case when p_status='FAILED' then now()+make_interval(secs=>least(900,15*attempt)) else available_at end,lease_token=null,lease_owner=null,lease_expires_at=null,updated_at=now() where id=p_id and status='CLAIMED' and lease_token=p_lease_token and lease_expires_at>now();get diagnostics n=row_count;return n=1;end$$;
revoke all on function public.claim_phase_o_agent_jobs(text,integer,integer),public.finish_phase_o_agent_job(uuid,uuid,text,jsonb,text) from public,anon,authenticated;grant execute on function public.claim_phase_o_agent_jobs(text,integer,integer),public.finish_phase_o_agent_job(uuid,uuid,text,jsonb,text) to service_role;

create or replace view public.phase_o_funnel_safe with(security_invoker=true) as select campaign_id,count(*) filter(where event_type='LANDING_VISIT') landing_visits,count(*) filter(where event_type='CLICK') clicks,count(distinct customer_id) filter(where event_type='SIGNUP') signups,count(distinct customer_id) filter(where event_type='CHECKOUT_ATTEMPT') checkout_attempts,count(distinct customer_id) filter(where event_type='ENTITLEMENT_VERIFIED') paid_vip_customers,count(distinct customer_id) filter(where event_type='MEMBERSHIP_CONFIRMED' and audience='FREE') free_members,count(distinct customer_id) filter(where event_type='MEMBERSHIP_CONFIRMED' and audience='VIP_FOREX_GOLD') vip_forex_gold_members,count(distinct customer_id) filter(where event_type='MEMBERSHIP_CONFIRMED' and audience='VIP_CRYPTO') vip_crypto_members from phase_o_attribution_events group by campaign_id;
revoke all on public.phase_o_funnel_safe from anon,authenticated;grant select on public.phase_o_funnel_safe to authenticated;

-- Reuse Phase-M publication work while resolving the two VIP destinations from canonical signal truth.
alter table public.signal_publication_work drop constraint if exists signal_publication_work_destination_check;
alter table public.signal_publication_work add constraint signal_publication_work_destination_check check(destination in('free','vip','vip_forex_gold','vip_crypto','customer','admin','owner'));
create or replace function public.phase_o_route_vip_publication() returns trigger language plpgsql set search_path=public as $$declare market text;symbol text;begin if new.destination<>'vip' then return new;end if;if new.signal_id is null then raise exception 'UNKNOWN_MARKET_CLASSIFICATION';end if;select upper(market_type),upper(s.symbol) into market,symbol from signals s where s.id=new.signal_id;if market='CRYPTO' or symbol~'(USDT|USDC|BTC|ETH)$' then new.destination:='vip_crypto';elsif market in('FOREX','METALS','GOLD') or symbol~'^(XAU|XAG)' or symbol~'^[A-Z]{6}$' then new.destination:='vip_forex_gold';else raise exception 'UNKNOWN_MARKET_CLASSIFICATION';end if;return new;end$$;
drop trigger if exists trg_phase_o_route_vip_publication on public.signal_publication_work;
create trigger trg_phase_o_route_vip_publication before insert on public.signal_publication_work for each row execute function public.phase_o_route_vip_publication();
